/* DPCT_ORIG     __inline__ __host__ __device__ double sgn(double x) {*/
    __inline__ double sgn(double x) {
        return (double(0) < x) - (x < double(0));
    }

/* DPCT_ORIG     __inline__ __host__ __device__ float sgn(float x) {*/
    __inline__ float sgn(float x) {
        return (float) ((float(0) < x) - (x < float(0)));
    }

/* DPCT_ORIG     template<class T>
    __inline__ __host__ __device__ complext<T> sgn(complext<T> x) {*/
    template <class T> __inline__ complext<T> sgn(complext<T> x) {
        if (norm(x) <= T(0)) return complext<T>(0);
        return (x / abs(x));
    }

/* DPCT_ORIG     template<class T>
    __inline__ __host__ __device__ complext<T> polar(const T &rho, const T &theta = 0) {*/
    template <class T> __inline__ complext<T> polar(const T& rho, const T& theta = 0) {
        return complext<T>(rho * std::cos(theta), rho * std::sin(theta));
    }

/* DPCT_ORIG     template<class T>
    __inline__ __host__ __device__ complext<T> sqrt(complext<T> x) {*/
    template <class T> __inline__ complext<T> sqrt(complext<T> x) {
        T r = abs(x);
/* DPCT_ORIG         return complext<T>(::sqrt((r + x.real()) / 2), sgn(x.imag()) * ::sqrt((r - x.real()) / 2));*/
        return complext<T>(sycl::sqrt((r + x.real()) / 2), sgn(x.imag()) * sycl::sqrt((r - x.real()) / 2));
    }

/* DPCT_ORIG     template<class T>
    __inline__ __host__ __device__ T abs(complext<T> comp) {*/
    template <class T> __inline__ T abs(complext<T> comp) {
/* DPCT_ORIG         return sqrt(comp._real * comp._real + comp._imag * comp._imag);*/
        return sycl::sqrt(comp._real * comp._real + comp._imag * comp._imag);
    }

/* DPCT_ORIG     template<class T>
    __inline__ __host__ __device__ complext<T> sin(complext<T> comp) {*/
    template <class T> __inline__ complext<T> sin(complext<T> comp) {
        return complext<T>(sin(comp._real) * std::cosh(comp._imag), std::cos(comp._real) * std::sinh(comp._imag));
    }

/* DPCT_ORIG     template<class T>
    __inline__ __host__ __device__ complext<T> cos(complext<T> comp) {*/
    template <class T> __inline__ complext<T> cos(complext<T> comp) {
        return complext<T>(cos(comp._real) * cosh(comp._imag), -sin(comp._real) * sinh(comp._imag));
    }

/* DPCT_ORIG     template<class T>
    __inline__ __host__ __device__ complext<T> exp(complext<T> com) {*/
    template <class T> __inline__ complext<T> exp(complext<T> com) {
        return exp(com._real) * complext<T>(cos(com._imag), sin(com._imag));
    }

/* DPCT_ORIG     template<class T>
    __inline__ __host__ __device__ T imag(complext<T> comp) {*/
    template <class T> __inline__ T imag(complext<T> comp) {
        return comp._imag;
    }

/* DPCT_ORIG     __inline__ __host__ __device__ double real(double r) {*/
