            std::stringstream err("cuNDArray::allocate_memory() : Error allocating CUDA memory");
            err << "CUDA Memory: " << free << " (" << total << ")";

            err << "   memory requested: " << size << "( ";
            for (size_t i = 0; i < this->dimensions_.size(); i++) {
                std::cerr << this->dimensions_[i] << " ";
            }
            err << ")";
            this->data_ = 0;
