  size_t max_idx = amax(x);
  T max_val_before;
/* DPCT_ORIG   CUDA_CALL(cudaMemcpy(&max_val_before, &x->get_data_ptr()[max_idx], sizeof(T), cudaMemcpyDeviceToHost));*/
