  {
    
    std::vector<size_t> dims_out = in.get_dimensions();
    for( unsigned int i=0; i<D; i++ ) dims_out[i] >>= 1;
    cuNDArray<T> out(dims_out);
    downsample<T,D>( in, out );
    return out;
  }

