/* DPCT_ORIG template <class REAL, unsigned int D>
__global__ void CorneliusKanade_kernel(const REAL*, const REAL*, const REAL*, REAL*, typename uintd<D>::Type,
                                       unsigned int, REAL, REAL, REAL, unsigned int*);*/
template <class REAL, unsigned int D>
void CorneliusKanade_kernel(const REAL*, const REAL*, const REAL*, REAL*, typename uintd<D>::Type, unsigned int, REAL,
                            REAL, REAL, unsigned int*, char* _shared_mem);

//
